#nullable enable // autogenerated

using MVZ2.GameContent.Artifacts;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Definitions;
using PVZEngine.Level;

namespace MVZ2.GameContent.Stages
{
    [StageDefinition(VanillaStageNames.pushingBox)]
    public partial class PushingBoxStage : StageDefinition
    {
        public PushingBoxStage(string nsp, string name) : base(nsp, name)
        {
            AddBehaviour(new WaveStageBehaviour(this));
            AddBehaviour(new FinalWaveClearBehaviour(this));
            AddBehaviour(new GemStageBehaviour(this));
            AddBehaviour(new StarshardStageBehaviour(this));
            AddBehaviour(new BlueprintCrisisBehaviour(this));
        }
        public override void OnStart(LevelEngine level)
        {
            level.SetArtifactSlotCount(1);
            level.ReplaceArtifacts(new NamespaceID[]
            {
                VanillaArtifactID.hoe,
            });
        }
    }
}